const prep=[['Sunday batch-cook chickpeas, rajma and lobia','रविवारी हरभरा, राजमा आणि चवळी शिजवून ठेवणे','2026-09-06','Meal Prep'],['Sprout matki and moong','मटकी आणि मूग मोड आणणे','2026-09-06','Batter / Sprouting'],['Prepare dosa/idli batter','डोसा/इडली बॅटर तयार करणे','2026-09-06','Batter / Sprouting'],['Make peanut-coriander chutney powder','शेंगदाणा-कोथिंबीर चटणी पूड तयार करणे','2026-09-06','Meal Prep'],['Make ground flaxseed portion','जवसाची पूड छोटे भाग करून ठेवणे','2026-09-06','Storage'],['Pre-portion roasted chana and peanuts','भाजलेला हरभरा आणि शेंगदाणे मोजून भाग करणे','2026-09-06','Meal Prep'],['Prepare shopping list for Month 1 week 1','पहिल्या आठवड्याची खरेदी यादी तयार करणे','2026-09-06','Shopping'],['Review Vikas food-reaction log','विकासच्या अन्न-प्रतिक्रिया नोंदी तपासणे','2026-09-13','Review']].map((x,i)=>({id:'p'+i,task:x[0],mr:x[1],date:x[2],area:x[3],done:false}));
const starter={version:1,members:family,meals:makeMeals(),recipes:recipeObj,shopping:shoppingNames.map((x,i)=>({id:'s'+i,item:x[0],mr:x[1],category:x[2],quantity:x[3],need:false,purchased:false})),prep,healthTips:[],healthTargets:[],householdSettings:{householdSize:4,oilStockMl:5000,oilMonthlyTargetMl:3000,displayName:'कुटुंब भोजन'},updatedAt:new Date().toISOString()};
function clone(x){return JSON.parse(JSON.stringify(x))}
function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE)||'null');return x&&x.version===1?x:clone(starter)}catch{return clone(starter)}}
let state=load();let page='today';let selectedDate=new Date().toISOString().slice(0,10);let selectedRecipe=null;let toastTimer;
let theme=localStorage.getItem(THEME_STORAGE)||'system';
let cloudRefreshTimer=null;
let cloudInitializing=false;
let cloudApplyingRemote=false;

async function save(){
 state.updatedAt=new Date().toISOString();
 localStorage.setItem(STORAGE,JSON.stringify(state));
 if(remoteReady&&!cloudApplyingRemote)await syncLocalChanges();
 toast('जतन झाले · Saved');
}
async function syncLocalChanges(){
 if(!remoteHouseholdId)return;
 const rows=buildRemoteRows(state,remoteHouseholdId);
 const conflicts={'meal_entries':'household_id,meal_date,slot','recipes':'household_id,recipe_key','family_members':'household_id,member_key','shopping_items':'household_id,item_key','prep_tasks':'household_id,task_key'};
 const batches=REMOTE_TABLES.map(table=>[table,rows[table],conflicts[table]]);
 for(const [table,payload,onConflict] of batches){
  const {error}=await supabase.from(table).upsert(payload,{onConflict});
  if(error){console.warn(`sync failed for ${table}`,error);toast('Cloud sync error · क्लाउड जतन अयशस्वी');return false;}
 }
 return true;
}
async function seedRemote(){
 const rows=buildRemoteRows(state,remoteHouseholdId);
 const conflicts={'meal_entries':'household_id,meal_date,slot','recipes':'household_id,recipe_key','family_members':'household_id,member_key','shopping_items':'household_id,item_key','prep_tasks':'household_id,task_key'};
 const batches=REMOTE_TABLES.map(table=>[table,rows[table],conflicts[table]]);
 for(const [table,payload,onConflict] of batches){
  const {error}=await supabase.from(table).upsert(payload,{onConflict});
  if(error)throw error;
 }
}
async function loadRemote(){
 const [a,b,c,d,e,f,g,h]=await Promise.all([
  supabase.from('meal_entries').select('*').eq('household_id',remoteHouseholdId),
  supabase.from('recipes').select('*').eq('household_id',remoteHouseholdId),
  supabase.from('family_members').select('*').eq('household_id',remoteHouseholdId).order('sort_order'),
  supabase.from('shopping_items').select('*').eq('household_id',remoteHouseholdId),
  supabase.from('prep_tasks').select('*').eq('household_id',remoteHouseholdId).order('task_date'),
  supabase.from('health_tips').select('*').eq('active',true).order('sort_order'),
  supabase.from('health_targets').select('*').eq('active',true).order('sort_order'),
  supabase.from('household_settings').select('*').eq('household_id',remoteHouseholdId).maybeSingle()
 ]);
 const err=[a,b,c,d,e,f,g,h].find(x=>x.error)?.error;
 if(err)throw err;
 const wasSeeded=!a.data?.length;
 if(wasSeeded) await seedRemote();
 if(wasSeeded){
  state.healthTips=mapHealthTips(f.data);
  state.healthTargets=mapHealthTargets(g.data);
  state.householdSettings=mapHouseholdSettings(h.data) || state.householdSettings;
  localStorage.setItem(STORAGE,JSON.stringify(state));
  return;
 }
 cloudApplyingRemote=true;
 try{
  state=mapRemoteState({members:c.data,meals:a.data,recipes:b.data,shopping:d.data,prep:e.data}, state);
  state.healthTips=mapHealthTips(f.data);
  state.healthTargets=mapHealthTargets(g.data);
  state.householdSettings=mapHouseholdSettings(h.data) || state.householdSettings;
  localStorage.setItem(STORAGE,JSON.stringify(state));
 }finally{cloudApplyingRemote=false;}
}
function subscribeToHousehold(){
 if(!remoteHouseholdId)return;
 if(realtimeChannel)supabase.removeChannel(realtimeChannel);
 const tables=[...REMOTE_TABLES,'household_settings'];
 realtimeChannel=supabase.channel(`kutumb-bhojan-${remoteHouseholdId}`);
 for(const table of tables){
  realtimeChannel=realtimeChannel.on('postgres_changes',{event:'*',schema:'public',table,filter:`household_id=eq.${remoteHouseholdId}`},()=>scheduleRemoteRefresh());
 }
 realtimeChannel.subscribe(status=>{if(status==='CHANNEL_ERROR')console.warn('Realtime channel error');});
}
function scheduleRemoteRefresh(){
 clearTimeout(cloudRefreshTimer);
 cloudRefreshTimer=setTimeout(async()=>{
  if(!remoteReady||cloudApplyingRemote)return;
  try{await loadRemote();render();}catch(err){console.warn('realtime refresh failed',err);}
 },250);
}
function cleanupCloud(){
 clearTimeout(cloudRefreshTimer);
 if(realtimeChannel){supabase.removeChannel(realtimeChannel);realtimeChannel=null;}
 remoteReady=false;
 remoteHouseholdId=null;
}
async function initCloud(){
 if(cloudInitializing)return;
 cloudInitializing=true;
 try{
  let {data:{session}}=await supabase.auth.getSession();
  if(!session){
   const {data,error}=await supabase.auth.signInAnonymously();
   if(error)throw error;
   session=data.session;
  }
  const {data,error}=await supabase.rpc('bootstrap_household',{household_name:'कुटुंब भोजन'});
  if(error)throw error;
  remoteHouseholdId=data;
  await loadRemote();
  remoteReady=true;
  subscribeToHousehold();
  render();
 }catch(err){
  console.error('Cloud initialization failed',err);
  cleanupCloud();
  render();
  toast('Cloud sync unavailable · क्लाउड sync उपलब्ध नाही. Local data चालू आहे.');
 }finally{cloudInitializing=false;}
}
supabase.auth.onAuthStateChange((_event,session)=>{
 if(session&&!remoteReady)initCloud();
 if(!session){cleanupCloud();initCloud();}
});

function toast(msg){clearTimeout(toastTimer);const el=document.getElementById('toast');if(!el)return;el.textContent='✓ '+msg;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),1600)}
function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function dateLabel(d){return new Intl.DateTimeFormat('mr-IN',{weekday:'long',day:'numeric',month:'long'}).format(new Date(d+'T00:00:00'))}
function fmt(d){return new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'short'}).format(new Date(d+'T00:00:00'))}
function findRecipe(title){return state.recipes.find(r=>r.name.toLowerCase()===title.toLowerCase())||null}
function applyTheme(){document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme==='system'?'light dark':theme}
function setTheme(value){theme=value;localStorage.setItem(THEME_STORAGE,value);applyTheme();render()}
function mealCard(m){return `<article class="meal-card"><div class="meal-slot"><span>${icon[m.slot]}</span><div><b>${slotMr[m.slot]}</b><small>${m.slot}</small></div></div><h3>${esc(m.marathi)}</h3><p>${esc(m.title)}</p><button class="link" data-recipe="${esc(m.title)}">पाककृती पाहा · View recipe →</button></article>`}
function head(k,t,s,action=''){return `<div class="section-head"><div><div class="kicker">${k}</div><h2>${t}</h2><p>${s}</p></div>${action}</div>`}
function healthTipCard(t,compact=false){return `<article class="health-card ${compact?'compact':''}"><div class="health-card-top"><span class="health-category">${esc(t.category)}</span><span>🌿</span></div><h3>${esc(t.mrTitle)}</h3><p class="health-en">${esc(t.title)}</p><p>${esc(t.mrSummary)}</p><div class="health-action"><b>आजचा छोटा बदल · Small action</b><p>${esc(t.mrAction)}</p></div>${compact?'':`<details><summary>अधिक माहिती · More</summary><p>${esc(t.mrDetail)}</p><p class="muted">${esc(t.detail)}</p>${t.sourceUrl?`<a href="${esc(t.sourceUrl)}" target="_blank" rel="noreferrer">${esc(t.sourceLabel||'Source')}</a>`:''}</details>`}</article>`}
function oilSnapshot(){const s=state.householdSettings||starter.householdSettings;const size=Math.max(1,Number(s.householdSize)||4);const target=Math.max(1,Number(s.oilMonthlyTargetMl)||3000);const stock=Math.max(0,Number(s.oilStockMl)||0);const daily=(target/30).toFixed(0);const perPerson=(target/30/size).toFixed(0);const status=stock<=target?'Within target':'Stock above target';return `<div class="target-card oil-target"><div class="target-icon">🫗</div><div><div class="kicker">HOUSEHOLD TARGET · घरचा target</div><h3>तेल / Oil</h3><p>${stock.toLocaleString('en-IN')} ml stock · ${status}</p></div><div class="target-values"><strong>${target.toLocaleString('en-IN')} ml</strong><span>monthly planning target</span></div><div class="target-meta"><span>≈ ${daily} ml/day household</span><span>≈ ${perPerson} ml/person/day</span></div><button class="secondary" data-page="settings">Target बदलायचा? →</button></div>`}
function targetCards(){return (state.healthTargets||[]).filter(x=>x.id!=='household_oil_planning').slice(0,4).map(t=>`<article class="target-mini"><span>${esc(t.category)}</span><strong>${esc(t.valueText||t.value)} ${esc(t.unit||'')}</strong><b>${esc(t.mrLabel)}</b><small>${esc(t.mrContext)}</small></article>`).join('')}
function today(){const meals=state.meals.filter(x=>x.date===selectedDate);const tasks=state.prep.filter(x=>x.date===selectedDate);const buy=state.shopping.filter(x=>x.need&&!x.purchased).length;const tip=state.healthTips?.[0];return `${head('TODAY · आज','आज काय बनवायचे?','जेवण, तयारी, खरेदी आणि आरोग्य — एका स्क्रीनवर.')}<div class="day-picker"><button data-day="prev">←</button><input id="date" type="date" value="${selectedDate}"><button data-day="next">→</button></div><div class="meal-grid">${meals.map(mealCard).join('')}</div><div class="dashboard-health">${tip?healthTipCard(tip,true):''}${oilSnapshot()}</div><div class="target-grid">${targetCards()}</div><div class="three-col"><div class="panel"><div class="panel-title">🔪 आजची तयारी / Today’s prep</div>${tasks.length?tasks.map(t=>`<label class="check-row"><input type="checkbox" data-prep="${t.id}" ${t.done?'checked':''}><span><b>${esc(t.mr)}</b><small>${esc(t.task)}</small></span></label>`).join(''):'<p class="muted">आजची तयारी नाही.</p>'}</div><div class="panel"><div class="panel-title">🛒 खरेदी / Shopping</div><div class="big-number">${buy}</div><p>items to buy / खरेदी करायच्या वस्तू</p><button class="primary" data-page="shopping">खरेदी यादी उघडा →</button></div><div class="panel"><div class="panel-title">🌿 Health Guide</div><p>तेल, मीठ, साखर, भाज्या, protein आणि food safety याबद्दल practical guidance.</p><button class="primary" data-page="health">आरोग्य मार्गदर्शन →</button></div></div>`}
function calendar(){const month=selectedDate.slice(0,7);const dates=[...new Set(state.meals.filter(x=>x.date.startsWith(month)).map(x=>x.date))];return `${head('CALENDAR · कॅलेंडर','कुटुंबाचे जेवणाचे वेळापत्रक','महिन्याच्या प्रत्येक दिवशी चार meal slots.')}<div class="toolbar"><input id="month" type="month" value="${month}"><span>${dates.length} days · ${dates.length*4} meal entries</span></div><div class="calendar-grid">${dates.map(d=>`<button class="calendar-day ${d===selectedDate?'selected':''}" data-select-date="${d}"><strong>${new Date(d+'T00:00:00').getDate()}</strong><span>${fmt(d)}</span><em>4 meals</em></button>`).join('')}</div><div class="selected-day"><h3>${dateLabel(selectedDate)}</h3>${state.meals.filter(x=>x.date===selectedDate).map(mealCard).join('')}</div>`}
function recipesView(){return `${head('RECIPES · पाककृती','कसे बनवायचे?','कुटुंबासाठी निवडलेल्या पाककृती — ingredients, time, portions आणि nutrition notes.')}<div class="search"><input id="recipeSearch" placeholder="पाककृती शोधा / Search recipes…"><span id="recipeCount">${state.recipes.length} recipes</span></div><div id="recipeGrid" class="recipe-grid">${state.recipes.map(r=>recipeCard(r)).join('')}</div>`}
function recipeCard(r){return `<button class="recipe-card" data-recipe-id="${r.id}"><div class="recipe-top"><span>🍲</span><small>${esc(r.time)}</small></div><h3>${esc(r.mr)}</h3><p>${esc(r.name)}</p><div class="metrics"><span>💪 ${esc(r.protein)}</span><span>🌾 ${esc(r.fibre)}</span><span>🔥 ${esc(r.cal)}</span></div></button>`}
function detail(r){return `<div><button class="back" data-back>← मागे / Back</button><div class="detail"><div class="detail-head"><div><div class="kicker">RECIPE · पाककृती</div><h2>${esc(r.mr)}</h2><p>${esc(r.name)}</p></div><div class="hero-metrics"><b>${esc(r.time)}</b><span>4 servings</span></div></div><div class="detail-grid"><div><h3>साहित्य / Ingredients</h3><ul>${r.ingredients.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>कृती / Method</h3><ol>${r.method.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></div><div class="metrics big"><span>💪 Protein ${esc(r.protein)}</span><span>🌾 Fibre ${esc(r.fibre)}</span><span>🔥 Calories ${esc(r.cal)}</span><span>🫗 Oil ${esc(r.oil)}</span></div><div class="note"><b>Notes / नोंदी</b><p>${esc(r.note)}</p></div></div></div>`}
function shopping(){const rows=state.shopping.map(x=>`<div class="shop-row ${x.purchased?'done':''}"><input type="checkbox" data-purchased="${x.id}" ${x.purchased?'checked':''}><div><b>${esc(x.mr)}</b><small>${esc(x.item)} · ${esc(x.category)}</small></div><strong>${esc(x.quantity)}</strong><label class="buy-pill"><input type="checkbox" data-need="${x.id}" ${x.need?'checked':''}><span>खरेदी करायची</span></label></div>`).join('');return `${head('SHOPPING · खरेदी','काय आणायचे?','हीच यादी बाजारात घेऊन जा. Checkbox प्रत्यक्ष काम करतो.')}<div class="toolbar"><span>${state.shopping.filter(x=>x.need&&!x.purchased).length} to buy / खरेदी बाकी</span></div><div class="shopping-list">${rows}</div>`}
function prepView(){return `${head('PREP · तयारी','आधी काय करायचे?','Batch prep केल्याने weekday cooking सोपी होते.')}<div class="prep-list">${state.prep.map(t=>`<label class="prep-row ${t.done?'done':''}"><input type="checkbox" data-prep="${t.id}" ${t.done?'checked':''}><div><b>${esc(t.mr)}</b><small>${esc(t.task)}</small></div><span>${fmt(t.date)}</span><em>${esc(t.area)}</em></label>`).join('')}</div>`}
function familyView(){return `${head('FAMILY · कुटुंब','कुटुंबातील सदस्य','ही माहिती reference साठी आहे; medical prescription नाही.')}<div class="family-grid">${state.members.map(m=>`<article class="person-card"><div class="avatar">${esc(m.name[0])}</div><h3>${esc(m.mr)}</h3><p>${esc(m.name)} · ${esc(m.age)} years</p><div class="person-stats"><span>${esc(m.weight)} kg</span><span>${esc(m.height)} cm</span></div><b>${esc(m.activity)}</b><p class="muted">${esc(m.note)}</p></article>`).join('')}</div>`}
function healthView(){const cats=[...new Set((state.healthTips||[]).map(x=>x.category))];return `${head('HEALTH GUIDE · आरोग्य','आरोग्य मार्गदर्शन','कुटुंबाच्या रोजच्या निर्णयांसाठी practical bilingual guidance. हे general information आहे; medical prescription नाही.')}<div class="health-notice">🌿 <b>Simple rule:</b> adequacy, balance, moderation and variety. Numeric values below are general references, not individual medical targets.</div><div class="health-filter"><button class="secondary health-filter-btn active" data-health-category="all">सर्व / All</button>${cats.map(c=>`<button class="secondary health-filter-btn" data-health-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div id="healthGrid" class="health-grid">${(state.healthTips||[]).map(t=>healthTipCard(t)).join('')}</div><div class="target-grid health-targets">${targetCards()}</div><div class="source-note">Health references are sourced from WHO public-health guidance and are stored with the content record so the family can review the source when needed.</div>`}
function settings(){const s=state.householdSettings||starter.householdSettings;return `${head('SETTINGS · सेटिंग्ज','डेटा आणि appearance','Shared household settings cloud मध्ये; theme या device वर जतन होतो.')}<div class="settings-grid"><div class="panel"><h3>🌗 Theme / थीम</h3><p>प्रत्येक device वर Light, Dark किंवा System निवडा.</p><div class="theme-switcher">${['light','dark','system'].map(x=>`<button class="${theme===x?'active':''}" data-theme="${x}">${x==='light'?'☀️ Light':x==='dark'?'🌙 Dark':'🖥️ System'}</button>`).join('')}</div></div><div class="panel"><h3>🫗 Oil planning / तेल नियोजन</h3><p>Stock आणि monthly planning target वेगळे ठेवा. हा household planning tool आहे; medical limit नाही.</p><label class="field"><span>Current stock (ml)</span><input id="oilStock" type="number" min="0" step="100" value="${esc(s.oilStockMl)}"></label><label class="field"><span>Monthly target (ml)</span><input id="oilTarget" type="number" min="100" step="100" value="${esc(s.oilMonthlyTargetMl)}"></label><label class="field"><span>Household size</span><input id="householdSize" type="number" min="1" max="20" step="1" value="${esc(s.householdSize)}"></label><div class="oil-advice"><b>कुठे कमी करायचे?</b><p>डीप-फ्राय, जास्त तेलाचा तडका आणि खूप तेलकट gravy आधी कमी करा. मोजून तेल वापरा; योग्य ठिकाणी भाजणे, वाफवणे, pressure cooking किंवा कमी तेलात cooking वापरा.</p></div><button class="primary" data-save-settings>Settings जतन करा</button></div><div class="panel"><h3>💾 Backup / बॅकअप</h3><p>दर काही दिवसांनी JSON backup डाउनलोड करा. नवीन फोनवर Import करून data परत आणता येईल.</p><button class="primary" data-export>⬇ Backup डाउनलोड</button><label class="secondary upload">⬆ Backup Import<input id="importFile" type="file" accept="application/json"></label></div><div class="panel"><h3>☁️ Cloud sync / क्लाउड जतन</h3><p>Login/OTP लागत नाही. प्रत्येक device ला anonymous session मिळतो आणि shared household data Supabase मध्ये sync होतो.</p><p class="muted">Health content Supabase मधून येतो; content बदलण्यासाठी frontend code बदलण्याची गरज नाही.</p></div><div class="panel"><h3>↺ Starter data / सुरुवातीचा डेटा</h3><p>Starter calendar, recipes, shopping आणि prep पुन्हा आणा. Local edits replace होतील.</p><button class="danger" data-reset>Reset starter data</button></div></div>`}
function render(){const nav=[['today','🏠','आज'],['calendar','📅','कॅलेंडर'],['recipes','🍳','पाककृती'],['health','🌿','आरोग्य'],['shopping','🛒','खरेदी'],['prep','🔪','तयारी'],['family','👨‍👩‍👦','कुटुंब'],['settings','⚙️','सेटिंग्ज']];let body=selectedRecipe?detail(selectedRecipe):page==='today'?today():page==='calendar'?calendar():page==='recipes'?recipesView():page==='health'?healthView():page==='shopping'?shopping():page==='prep'?prepView():page==='family'?familyView():settings();document.getElementById('app').innerHTML=`<header class="topbar"><div><div class="eyebrow">FAMILY NUTRITION · कुटुंबाचे पोषण</div><h1>🍛 कुटुंब भोजन <span>Kutumb Bhojan</span></h1></div><button class="date-chip" data-page="today">${dateLabel(selectedDate)}</button></header><main class="layout"><aside class="sidebar"><div class="brand-card"><div class="brand-icon">🍲</div><strong>सोपे कौटुंबिक जेवण</strong><small>Simple family nutrition system</small></div>${nav.map(n=>`<button class="nav ${page===n[0]?'active':''}" data-page="${n[0]}"><span>${n[1]}</span>${n[2]}</button>`).join('')}<div class="sidebar-note"><b>आजचे चार प्रश्न</b><br>काय बनवायचे? → Calendar<br>कसे बनवायचे? → Recipes<br>काय आणायचे? → Shopping<br>आधी काय करायचे? → Prep<br>आरोग्य कसे सुधारायचे? → Health</div></aside><section class="content">${body}</section></main><nav class="mobile-nav">${nav.slice(0,6).map(n=>`<button class="${page===n[0]?'active':''}" data-page="${n[0]}"><span>${n[1]}</span><small>${n[2]}</small></button>`).join('')}</nav><div id="toast"></div>`;bind()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;selectedRecipe=null;render()});const date=document.getElementById('date');if(date)date.onchange=()=>{selectedDate=date.value;render()};document.querySelector('[data-day="prev"]')?.addEventListener('click',()=>shiftDay(-1));document.querySelector('[data-day="next"]')?.addEventListener('click',()=>shiftDay(1));document.getElementById('month')?.addEventListener('change',e=>{selectedDate=e.target.value+'-01';render()});document.querySelectorAll('[data-select-date]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.selectDate;render()});document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>{const r=findRecipe(b.dataset.recipe);if(r){selectedRecipe=r;render()}else toast('Recipe detail not seeded yet / पाककृती तपशील लवकरच')});document.querySelectorAll('[data-recipe-id]').forEach(b=>b.onclick=()=>{selectedRecipe=state.recipes.find(r=>r.id===b.dataset.recipeId);render()});document.querySelector('[data-back]')?.addEventListener('click',()=>{selectedRecipe=null;render()});document.querySelectorAll('[data-prep]').forEach(i=>i.onchange=()=>{const x=state.prep.find(t=>t.id===i.dataset.prep);if(x){x.done=i.checked;save();render()}});document.querySelectorAll('[data-purchased]').forEach(i=>i.onchange=()=>{const x=state.shopping.find(t=>t.id===i.dataset.purchased);if(x){x.purchased=i.checked;save();render()}});document.querySelectorAll('[data-need]').forEach(i=>i.onchange=()=>{const x=state.shopping.find(t=>t.id===i.dataset.need);if(x){x.need=i.checked;save();render()}});document.getElementById('recipeSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();const list=state.recipes.filter(r=>`${r.name} ${r.mr} ${r.course}`.toLowerCase().includes(q));document.getElementById('recipeGrid').innerHTML=list.map(recipeCard).join('');document.getElementById('recipeCount').textContent=`${list.length} recipes` ;bind()});document.querySelectorAll('[data-health-category]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-health-category]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const q=b.dataset.healthCategory;document.getElementById('healthGrid').innerHTML=(state.healthTips||[]).filter(t=>q==='all'||t.category===q).map(healthTipCard).join('')});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme));document.querySelector('[data-save-settings]')?.addEventListener('click',async()=>{const s=state.householdSettings||clone(starter.householdSettings);s.oilStockMl=Math.max(0,Number(document.getElementById('oilStock').value)||0);s.oilMonthlyTargetMl=Math.max(100,Number(document.getElementById('oilTarget').value)||3000);s.householdSize=Math.min(20,Math.max(1,Number(document.getElementById('householdSize').value)||4));state.householdSettings=s;localStorage.setItem(STORAGE,JSON.stringify(state));const ok=await saveHouseholdSettings();if(ok)toast('घरची settings जतन झाली · Saved');render()});document.querySelector('[data-export]')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`kutumb-bhojan-backup-${new Date().toISOString().slice(0,10)}.json`;a.click()});document.getElementById('importFile')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(x.version!==1)throw new Error();state={...clone(starter),...x};localStorage.setItem(STORAGE,JSON.stringify(state));render();toast('Backup restored / बॅकअप परत आला')}catch{toast('Invalid backup / चुकीची बॅकअप फाइल')}};r.readAsText(file)});document.querySelector('[data-reset]')?.addEventListener('click',()=>{if(confirm('Reset local changes? / सर्व स्थानिक बदल काढायचे?')){state=clone(starter);save();render()}})}
function shiftDay(delta){const d=new Date(selectedDate+'T00:00:00');d.setUTCDate(d.getUTCDate()+delta);selectedDate=d.toISOString().slice(0,10);render()}
applyTheme();
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(err=>console.warn('service worker unavailable',err)));}
initCloud();
